def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    dx = me.x - enemy.x
    dy = me.y - enemy.y
    edist = sqrt(dx * dx + dy * dy)

    if edist > 0.05:
        toward = degrees(atan2(dy, dx))
        facing = (toward - enemy.heading + 180) % 360 - 180
    else:
        facing = 0

    tx = enemy.x
    ty = enemy.y

    if edist > 2.0 and edist < 8.5 and abs(facing) < 60:
        eh = radians(enemy.heading)
        sx = -sin(eh)
        sy = cos(eh)
        side = dx * sx + dy * sy
        sign = 1 if side >= 0 else -1
        offset = 1.45

        tx = enemy.x + sign * sx * offset
        ty = enemy.y + sign * sy * offset

        if sqrt(tx * tx + ty * ty) > 5.75:
            tx = enemy.x - sign * sx * offset
            ty = enemy.y - sign * sy * offset

    b = bearing_to(tx, ty)
    radial = sqrt(me.x * me.x + me.y * me.y)

    if radial > 5.75:
        b = bearing_to(0, 0)

    if b > 120:
        return (-0.55, 1.0)
    if b < -120:
        return (1.0, -0.55)

    turn = b * 0.025 - me.turn_rate * 0.02
    if turn > 1:
        turn = 1
    if turn < -1:
        turn = -1

    return (1 - turn, 1 + turn)


def weapons(me, enemy, arena):
    w = me.weapons.get("front")
