    if temp >= 110:
        cooling = True
    elif temp <= 85:
        cooling = False

    me.memory["cooling"] = cooling

    if cooling:
        rpm = w.get("rpm", 0)
        if rpm < 0:
            rpm = 0
        return spin("front", rpm)

    return spin("front", 3000)

